<script>
'use strict';
/* ============================== basics ============================== */
const TAU = Math.PI * 2;
const canvas = document.getElementById('scene');
const ctx = canvas.getContext('2d');
const readoutEl = document.getElementById('readout');
const clamp   = (v,a,b)=> v<a?a : v>b?b : v;
const clamp01 = v => clamp(v,0,1);
const wrapPi  = a => Math.atan2(Math.sin(a), Math.cos(a));
const hexRGB  = h => [parseInt(h.slice(1,3),16), parseInt(h.slice(3,5),16), parseInt(h.slice(5,7),16)];
const shade   = (h,amt)=>{ const[r,g,b]=hexRGB(h), f=v=>clamp(v+amt,0,255)|0; return `rgb(${f(r)},${f(g)},${f(b)})`; };
const rgba    = (h,a,amt=0)=>{ const[r,g,b]=hexRGB(h), f=v=>clamp(v+amt,0,255)|0; return `rgba(${f(r)},${f(g)},${f(b)},${a})`; };
const gauss   = ()=> Math.random()+Math.random()+Math.random()+Math.random()-2;

/* ============================== bodies ============================== */
const SUN = { name:'Sol', r:21, fact:'Main sequence · class G2V' };
const PLANETS = [
  {name:'Mercury', a:58,  r:3.2, col:'#9a8d80', fact:'Period 0.24 yr'},
  {name:'Venus',   a:82,  r:5.1, col:'#d8b986', fact:'Period 0.62 yr',  atmo:'#e6d3a3'},
  {name:'Earth',   a:108, r:5.6, col:'#5b86b8', fact:'Period 1.00 yr · 1 moon', atmo:'#7fb2e0',
    moon:{dist:15, r:1.8, col:'#b7b2a9', name:'Luna', fact:'Orbital 2.4 d · Earth satellite'}},
  {name:'Mars',    a:140, r:4.3, col:'#b56243', fact:'Period 1.88 yr'},
  {name:'Jupiter', a:192, r:13.5,col:'#c3a275', fact:'Period 11.9 yr · gas giant', bands:true},
  {name:'Saturn',  a:244, r:11,  col:'#d6bd8e', fact:'Period 29.5 yr · ringed',    rings:true},
  {name:'Uranus',  a:288, r:8,   col:'#8fc3cd', fact:'Period 84 yr · ice giant'},
  {name:'Neptune', a:326, r:7.7, col:'#5570c8', fact:'Period 165 yr · ice giant'}
];
const MAXA = 326, PERSP = 1500, K = 0.0125;           // Kepler-ish period scaling
const DEF_TILT = 0.58, DEF_PHI = -0.55;
PLANETS.forEach((p,i)=>{
  p.Tsec = K * Math.pow(p.a, 1.5);                    // seconds per simulated orbit
  p.w    = TAU / p.Tsec;                              // angular velocity
  p.th0  = 0.7 + i * 2.39996;                         // golden-angle spread of start phase
  p.lit  = shade(p.col, 55);
  p.dark = shade(p.col, -72);
  p.trailSpan = 0.55 + 0.45 * Math.min(1, 16 / p.Tsec);
  if(p.moon){ p.moon.lit = shade(p.moon.col,40); p.moon.dark = shade(p.moon.col,-60); p.moon.w = TAU/2.6; }
});

/* ============================== state ============================== */
let W=0,H=0,DPR=1,U=1,CX=0,CY=0,bg=null;
const cam = { tilt:DEF_TILT, phi:DEF_PHI, zoom:1, tTilt:DEF_TILT, tPhi:DEF_PHI, tZoom:1, vPhi:0, vTilt:0 };
let simT=0, wallT=0, simSpeed=1, paused=false;
let lastFrame=performance.now(), lastInteract=-10;
const RM = matchMedia('(prefers-reduced-motion: reduce)').matches;
const mouse = { x:0, y:0, has:false };
let dragging=false, hoverPick=null, pinchD0=0, pinchZ0=1;
const pointers = new Map();
let twinks=[], meteors=[], meteorTimer=4;

/* ============================ projection ============================ */
/* Orbital plane is a true 3D circle: azimuth yaw + elevation tilt + mild perspective */
function project(x,z){
  const ca=Math.cos(cam.phi), sa=Math.sin(cam.phi);
  const x1 = x*ca - z*sa, z1 = x*sa + z*ca;
  const st=Math.sin(cam.tilt), ct=Math.cos(cam.tilt);
  const d = z1*ct;                       // depth toward viewer
  const k = PERSP/(PERSP+d);             // perspective scale
  const sc = k*cam.zoom*U;
  return { x: CX + x1*sc, y: CY + z1*st*sc, k, d };
}

/* ============================ starfield ============================ */
function buildBackground(){
  bg = document.createElement('canvas');
  bg.width = W*DPR; bg.height = H*DPR;
  const c = bg.getContext('2d');
  c.setTransform(DPR,0,0,DPR,0,0);
  c.fillStyle = '#04060b'; c.fillRect(0,0,W,H);

  let g = c.createRadialGradient(CX,CY,0,CX,CY,Math.max(W,H)*0.75);
  g.addColorStop(0,'rgba(16,22,38,0.5)'); g.addColorStop(0.55,'rgba(10,14,26,0.22)'); g.addColorStop(1,'rgba(4,6,11,0)');
  c.fillStyle=g; c.fillRect(0,0,W,H);

  // faint galactic band: haze blobs + clustered stars
  const bx0=-0.12*W, by0=0.88*H, bx1=1.12*W, by1=0.08*H, m=Math.min(W,H);
  for(let i=0;i<6;i++){
    const t=(i+0.5)/6+(Math.random()-0.5)*0.08;
    const x=bx0+(bx1-bx0)*t, y=by0+(by1-by0)*t+(Math.random()-0.5)*30;
    const rr=(0.18+Math.random()*0.22)*m;
    g=c.createRadialGradient(x,y,0,x,y,rr);
    g.addColorStop(0, Math.random()<0.5?'rgba(122,132,172,0.045)':'rgba(150,140,150,0.04)');
    g.addColorStop(1,'rgba(0,0,0,0)');
    c.fillStyle=g; c.beginPath(); c.arc(x,y,rr,0,TAU); c.fill();
  }

  const N = Math.round(W*H/4200);
  twinks = [];
  for(let i=0;i<N;i++){
    let x,y;
    if(Math.random()<0.34){ const t=Math.random(); x=bx0+(bx1-bx0)*t; y=by0+(by1-by0)*t+gauss()*0.3*m; }
    else { x=Math.random()*W; y=Math.random()*H; }
    const r = 0.35 + Math.pow(Math.random(),2.2)*1.25;
    const a = 0.22 + Math.random()*0.6;
    const pal = Math.random()<0.72 ? '220,228,255' : (Math.random()<0.5?'255,243,224':'255,255,255');
    const star = {x,y,r,a,pal, ph:Math.random()*TAU, sp:0.4+Math.random()*1.8, px:0.35+Math.random()*0.65};
    if(r>1.05){ // soft halo on the brighter few
      const hg=c.createRadialGradient(x,y,0,x,y,r*4);
      hg.addColorStop(0,`rgba(${pal},${(a*0.35).toFixed(3)})`); hg.addColorStop(1,'rgba(0,0,0,0)');
      c.fillStyle=hg; c.beginPath(); c.arc(x,y,r*4,0,TAU); c.fill();
    }
    if(Math.random()<0.3) twinks.push(star);           // animated layer
    else { c.fillStyle=`rgba(${pal},${a.toFixed(3)})`; c.beginPath(); c.arc(x,y,r,0,TAU); c.fill(); }
  }
}
function drawStars(){
  const ox = Math.sin(cam.phi)*16, oy = (DEF_TILT-cam.tilt)*30;   // gentle parallax
  for(const s of twinks){
    const tw = RM ? 0.85+0.15*Math.sin(wallT*s.sp+s.ph) : 0.55+0.45*Math.sin(wallT*s.sp+s.ph);
    ctx.fillStyle = `rgba(${s.pal},${(s.a*tw).toFixed(3)})`;
    ctx.beginPath(); ctx.arc(s.x+ox*s.px, s.y+oy*s.px, s.r, 0, TAU); ctx.fill();
  }
}

/* ============================= meteors ============================= */
function stepMeteors(dt){
  if(RM) return;
  meteorTimer -= dt;
  if(meteorTimer<=0 && meteors.length<2){
    const fromLeft = Math.random()<0.5;
    meteors.push({
      x: W*(0.15+Math.random()*0.7), y: H*(0.05+Math.random()*0.4),
      ang: fromLeft ? 0.5+Math.random()*0.5 : Math.PI-0.5-Math.random()*0.5,
      sp: 300+Math.random()*260, len: 80+Math.random()*70, t:0, life:0.8+Math.random()*0.5
    });
    meteorTimer = 6+Math.random()*9;
  }
  for(let i=meteors.length-1;i>=0;i--){
    const m=meteors[i]; m.t+=dt;
    m.x+=Math.cos(m.ang)*m.sp*dt; m.y+=Math.sin(m.ang)*m.sp*dt;
    if(m.t>m.life) meteors.splice(i,1);
  }
}
function drawMeteors(){
  for(const m of meteors){
    const a = 0.5*Math.sin(Math.PI*Math.min(1,m.t/m.life));
    const tx = m.x-Math.cos(m.ang)*m.len, ty = m.y-Math.sin(m.ang)*m.len;
    const g = ctx.createLinearGradient(m.x,m.y,tx,ty);
    g.addColorStop(0,`rgba(210,225,255,${a.toFixed(3)})`); g.addColorStop(1,'rgba(210,225,255,0)');
    ctx.strokeStyle=g; ctx.lineWidth=1.1;
    ctx.beginPath(); ctx.moveTo(m.x,m.y); ctx.lineTo(tx,ty); ctx.stroke();
    ctx.fillStyle=`rgba(235,242,255,${a.toFixed(3)})`;
    ctx.beginPath(); ctx.arc(m.x,m.y,1.3,0,TAU); ctx.fill();
  }
}

/* ========================= scene components ========================= */
function drawPlaneHaze(){ // zodiacal light: faint warm haze inside the outermost orbit
  ctx.beginPath();
  for(let i=0;i<=64;i++){
    const th=i/64*TAU, q=project(Math.cos(th)*MAXA, Math.sin(th)*MAXA);
    i?ctx.lineTo(q.x,q.y):ctx.moveTo(q.x,q.y);
  }
  ctx.closePath();
  const R=MAXA*cam.zoom*U*1.06;
  const g=ctx.createRadialGradient(CX,CY,0,CX,CY,R);
  g.addColorStop(0,'rgba(255,170,100,0.07)');
  g.addColorStop(0.45,'rgba(255,160,90,0.035)');
  g.addColorStop(1,'rgba(255,150,80,0)');
  ctx.fillStyle=g; ctx.fill();
}
function drawOrbit(p){ // depth-shaded orbit segments: near side brighter
  const N=72, maxD=Math.max(1e-3, MAXA*Math.abs(Math.cos(cam.tilt)));
  let px=0,py=0,pd=0;
  for(let i=0;i<=N;i++){
    const th=i/N*TAU, q=project(Math.cos(th)*p.a, Math.sin(th)*p.a);
    if(i>0){
      const f=clamp01(0.5+0.5*((pd+q.d)*0.5)/maxD);
      ctx.strokeStyle=`rgba(150,168,206,${(0.035+0.085*f).toFixed(3)})`;
      ctx.lineWidth=1;
      ctx.beginPath(); ctx.moveTo(px,py); ctx.lineTo(q.x,q.y); ctx.stroke();
    }
    px=q.x; py=q.y; pd=q.d;
  }
}
function drawTrail(p,th){ // short fading arc along the orbit, always correct under camera motion
  const N=18; let nx=0,ny=0;
  for(let i=0;i<=N;i++){
    const a=th-p.trailSpan*(i/N), q=project(Math.cos(a)*p.a, Math.sin(a)*p.a);
    if(i>0){
      const f=1-i/N;
      ctx.strokeStyle=rgba(p.col, 0.30*f*f, 50);
      ctx.lineWidth=Math.max(0.5, p.r*q.k*cam.zoom*U*0.5*f);
      ctx.beginPath(); ctx.moveTo(nx,ny); ctx.lineTo(q.x,q.y); ctx.stroke();
    }
    nx=q.x; ny=q.y;
  }
}
function drawMoonPath(p,ew){
  ctx.strokeStyle='rgba(150,168,206,0.10)'; ctx.lineWidth=1;
  ctx.beginPath();
  for(let i=0;i<=36;i++){
    const a=i/36*TAU, q=project(ew.wx+Math.cos(a)*p.moon.dist, ew.wz+Math.sin(a)*p.moon.dist);
    i?ctx.lineTo(q.x,q.y):ctx.moveTo(q.x,q.y);
  }
  ctx.stroke();
}
function drawRingSystem(p,it,pass){ // far half drawn behind the disc, near half in front
  const bands=[{f:1.42,w:0.36,al:0.40},{f:1.80,w:0.22,al:0.28},{f:2.08,w:0.11,al:0.18}];
  const N=64, maxD=Math.max(1e-3, MAXA*Math.abs(Math.cos(cam.tilt)));
  for(const b of bands){
    let prev=null;
    for(let i=0;i<=N;i++){
      const be=i/N*TAU, q=project(it.wx+Math.cos(be)*p.r*b.f, it.wz+Math.sin(be)*p.r*b.f);
      if(prev){
        const isFar=((prev.d+q.d)*0.5) < it.s.d;
        if(pass===(isFar?0:1)){
          const tex=0.78+0.22*Math.sin(be*2.3+1.1);
          const dF=clamp01(0.5+0.5*((prev.d+q.d)*0.5)/maxD);
          ctx.strokeStyle=rgba('#cdb48c', b.al*tex*(0.55+0.45*dF));
          ctx.lineWidth=Math.max(0.6, p.r*b.w*q.k*cam.zoom*U);
          ctx.beginPath(); ctx.moveTo(prev.x,prev.y); ctx.lineTo(q.x,q.y); ctx.stroke();
        }
      }
      prev=q;
    }
  }
}
function drawBands(s,pr){
  const B=[[-0.58,0.15,-16],[-0.32,0.11,12],[-0.05,0.16,-10],[0.22,0.12,14],[0.48,0.14,-14],[0.68,0.09,-8]];
  for(const[o,h,amt]of B){
    ctx.fillStyle=rgba('#c3a275',0.45,amt);
    ctx.fillRect(s.x-pr, s.y+o*pr-h*pr*0.5, pr*2, h*pr);
  }
  ctx.fillStyle='rgba(187,90,58,0.5)'; // Great Red Spot
  ctx.beginPath(); ctx.ellipse(s.x+pr*0.26, s.y+pr*0.34, pr*0.16, pr*0.09, 0, 0, TAU); ctx.fill();
}
function circlePath(x,y,r){ ctx.beginPath(); ctx.arc(x,y,r,0,TAU); }

function drawSun(it){
  const s=it.s, R=Math.max(6, SUN.r*s.k*cam.zoom*U);
  const pulse=1+0.035*Math.sin(wallT*1.3)+0.02*Math.sin(wallT*2.1+1.7);
  let g=ctx.createRadialGradient(s.x,s.y,R*0.2, s.x,s.y,R*3.6*pulse);   // outer corona
  g.addColorStop(0,'rgba(255,166,70,0.42)');
  g.addColorStop(0.35,'rgba(255,132,48,0.16)');
  g.addColorStop(1,'rgba(255,120,40,0)');
  ctx.fillStyle=g; ctx.beginPath(); ctx.arc(s.x,s.y,R*3.6*pulse,0,TAU); ctx.fill();
  g=ctx.createRadialGradient(s.x,s.y,R*0.3, s.x,s.y,R*1.75);            // inner glow
  g.addColorStop(0,'rgba(255,214,130,0.55)');
  g.addColorStop(1,'rgba(255,180,80,0)');
  ctx.fillStyle=g; ctx.beginPath(); ctx.arc(s.x,s.y,R*1.75,0,TAU); ctx.fill();
  g=ctx.createRadialGradient(s.x-R*0.18,s.y-R*0.18,R*0.1, s.x,s.y,R);   // photosphere
  g.addColorStop(0,'#fffbee'); g.addColorStop(0.45,'#ffdf8f');
  g.addColorStop(0.8,'#ffb347'); g.addColorStop(1,'#f08c2e');
  ctx.fillStyle=g; ctx.beginPath(); ctx.arc(s.x,s.y,R,0,TAU); ctx.fill();
  ctx.strokeStyle='rgba(255,190,110,0.5)'; ctx.lineWidth=1;
  ctx.beginPath(); ctx.arc(s.x,s.y,R+0.6,0,TAU); ctx.stroke();
}

function drawPlanetBody(it){
  const p=it.p, s=it.s;
  const pr=Math.max(1.1, p.r*s.k*cam.zoom*U);
  const maxD=Math.max(30, MAXA*Math.abs(Math.cos(cam.tilt)));
  const lx0=CX-s.x, ly0=CY-s.y, ll=Math.hypot(lx0,ly0)||1;
  const lx=lx0/ll, ly=ly0/ll, la=Math.atan2(ly,lx);
  const gx=s.x+lx*pr*0.45, gy=s.y+ly*pr*0.45;   // lit-side gradient focus (toward the sun)

  if(p.rings) drawRingSystem(p,it,0);

  let g=ctx.createRadialGradient(gx,gy,pr*0.05, s.x,s.y,pr*1.02);       // sphere base
  g.addColorStop(0,p.lit); g.addColorStop(0.6,p.col); g.addColorStop(1,p.dark);
  circlePath(s.x,s.y,pr); ctx.fillStyle=g; ctx.fill();

  if(pr>4){
    ctx.save(); circlePath(s.x,s.y,pr-0.3); ctx.clip();
    if(p.bands) drawBands(s,pr);
    g=ctx.createRadialGradient(gx,gy,pr*0.1, gx,gy,pr*2.1);             // terminator shadow
    g.addColorStop(0,'rgba(0,0,0,0)');
    g.addColorStop(0.4,'rgba(3,5,12,0.08)');
    g.addColorStop(0.72,'rgba(3,5,12,0.6)');
    g.addColorStop(1,'rgba(2,3,8,0.92)');
    ctx.fillStyle=g; ctx.fillRect(s.x-pr-1,s.y-pr-1,pr*2+2,pr*2+2);
    g=ctx.createRadialGradient(gx,gy,0, gx,gy,pr*0.9);                  // day-side highlight
    g.addColorStop(0,'rgba(255,250,238,0.28)');
    g.addColorStop(0.55,'rgba(255,246,226,0.07)');
    g.addColorStop(1,'rgba(255,246,226,0)');
    ctx.fillStyle=g; ctx.fillRect(s.x-pr-1,s.y-pr-1,pr*2+2,pr*2+2);
    ctx.restore();
  }
  if(p.atmo){                                                           // lit-limb atmosphere
    ctx.strokeStyle=rgba(p.atmo,0.32);
    ctx.lineWidth=Math.max(0.8,pr*0.14);
    ctx.beginPath(); ctx.arc(s.x,s.y,pr+ctx.lineWidth*0.3, la-1.3, la+1.3); ctx.stroke();
  }
  ctx.strokeStyle=rgba(p.col,0.55,85);                                  // rim light
  ctx.lineWidth=Math.max(0.6,pr*0.08);
  ctx.beginPath(); ctx.arc(s.x,s.y,Math.max(0.8,pr-ctx.lineWidth*0.4), la-1.15, la+1.15); ctx.stroke();

  if(s.d<0 && maxD>30){                                                 // dimmed while behind the sun
    const dd=Math.min(0.42, -s.d/maxD*0.5);
    circlePath(s.x,s.y,pr); ctx.fillStyle=`rgba(3,6,13,${dd.toFixed(3)})`; ctx.fill();
  }
  if(p.rings) drawRingSystem(p,it,1);
}

/* ============================== hover ============================== */
function drawHover(h){
  const s=h.it.s, pr=h.pr;
  const isSun=h.it.kind==='sun';
  const name=(isSun?SUN.name:h.it.p.name).toUpperCase();
  const fact=(isSun?SUN.fact:h.it.p.fact).toUpperCase();
  const flip=s.x>W-170, below=s.y<90;
  const a = below ? (flip? 3*Math.PI/4 : Math.PI/4) : (flip? -3*Math.PI/4 : -Math.PI/4);
  ctx.save();
  ctx.strokeStyle='rgba(230,235,245,0.55)'; ctx.lineWidth=1;
  ctx.setLineDash([3,4]); ctx.lineDashOffset=-wallT*10;
  ctx.beginPath(); ctx.arc(s.x,s.y,pr+6,0,TAU); ctx.stroke();
  ctx.setLineDash([]);
  const x0=s.x+Math.cos(a)*(pr+8), y0=s.y+Math.sin(a)*(pr+8);
  const x1=x0+Math.cos(a)*14,      y1=y0+Math.sin(a)*14;
  const x2=x1+(flip?-10:10),       y2=y1;
  ctx.strokeStyle='rgba(230,235,245,0.4)';
  ctx.beginPath(); ctx.moveTo(x0,y0); ctx.lineTo(x1,y1); ctx.lineTo(x2,y2); ctx.stroke();
  ctx.textAlign=flip?'right':'left';
  ctx.shadowColor='rgba(0,0,0,0.7)'; ctx.shadowBlur=4;
  ctx.letterSpacing='2px';
  ctx.font='600 11px Optima,"Palatino Linotype","Segoe UI",sans-serif';
  ctx.fillStyle='rgba(236,240,248,0.95)';
  ctx.fillText(name, x2+(flip?-6:6), y2-2);
  ctx.letterSpacing='1px';
  ctx.font='500 9px Optima,"Palatino Linotype","Segoe UI",sans-serif';
  ctx.fillStyle='rgba(160,170,190,0.9)';
  ctx.fillText(fact, x2+(flip?-6:6), y2+11);
  ctx.letterSpacing='0px';
  ctx.restore();
}

/* ============================== frame ============================== */
function drawVignette(){
  const R=Math.hypot(W,H)*0.6;
  const g=ctx.createRadialGradient(CX,CY,Math.min(W,H)*0.42, CX,CY,R);
  g.addColorStop(0,'rgba(2,3,8,0)'); g.addColorStop(1,'rgba(2,3,8,0.5)');
  ctx.fillStyle=g; ctx.fillRect(0,0,W,H);
}
function updateReadout(){
  const az=Math.round(((-cam.phi*180/Math.PI)%360+360)%360);
  const sp=simSpeed>=1? +simSpeed.toFixed(1) : +simSpeed.toFixed(2);
  readoutEl.textContent=`Tilt ${Math.round(cam.tilt*180/Math.PI)}° · az ${az}° · zoom ${cam.zoom.toFixed(2)}× · time ${sp}×`;
}
function render(){
  ctx.setTransform(DPR,0,0,DPR,0,0);
  ctx.drawImage(bg,0,0,W,H);
  drawStars(); drawMeteors();
  drawPlaneHaze();
  for(const p of PLANETS) drawOrbit(p);

  const items=[];
  for(const p of PLANETS){
    const th=p.th0+simT*p.w;
    const wx=Math.cos(th)*p.a, wz=Math.sin(th)*p.a;
    items.push({kind:'planet',p,th,wx,wz,s:project(wx,wz)});
    if(p.moon){
      const mth=simT*p.moon.w+1.2;
      const mx=wx+Math.cos(mth)*p.moon.dist, mz=wz+Math.sin(mth)*p.moon.dist;
      items.push({kind:'moon',p:p.moon,wx:mx,wz:mz,s:project(mx,mz)});
    }
  }
  items.push({kind:'sun',s:project(0,0)});
  items.sort((a,b)=>a.s.d-b.s.d);           // painter's algorithm: far → near

  hoverPick=null;
  const canPick=mouse.has && !dragging && pointers.size<2;
  for(const it of items){
    if(it.kind==='sun') drawSun(it);
    else{
      if(it.kind==='planet'){ drawTrail(it.p,it.th); if(it.p.moon) drawMoonPath(it.p,it); }
      drawPlanetBody(it);
    }
    if(canPick){
      const rr=it.kind==='sun'
        ? Math.max(6, SUN.r*it.s.k*cam.zoom*U)
        : Math.max(1.1, it.p.r*it.s.k*cam.zoom*U);
      const dx=mouse.x-it.s.x, dy=mouse.y-it.s.y, d2=dx*dx+dy*dy;
      if(d2<(rr+7)*(rr+7) && (!hoverPick || d2<hoverPick.d2)) hoverPick={it,pr:rr,d2};
    }
  }
  drawVignette();
  if(hoverPick) drawHover(hoverPick);
  const cur=dragging?'grabbing':(hoverPick?'pointer':'grab');
  if(canvas.style.cursor!==cur) canvas.style.cursor=cur;
  updateReadout();
}
function frame(now){
  const dt=Math.min(0.05,(now-lastFrame)/1000)||0;
  lastFrame=now; wallT+=dt;
  if(!paused) simT+=dt*simSpeed*(RM?0.35:1);

  if(!dragging){
    cam.tPhi += cam.vPhi*dt*60; cam.tTilt += cam.vTilt*dt*60;      // release inertia
    const dec=Math.pow(0.90,dt*60); cam.vPhi*=dec; cam.vTilt*=dec;
    if(Math.abs(cam.vPhi)<1e-4)cam.vPhi=0;
    if(Math.abs(cam.vTilt)<1e-4)cam.vTilt=0;
    if(wallT-lastInteract>4 && !RM) cam.tPhi+=dt*0.03;             // idle cinematic drift
  }
  cam.tTilt=clamp(cam.tTilt,0.10,1.42);
  cam.tilt +=(cam.tTilt-cam.tilt)*Math.min(1,dt*10);
  cam.phi  +=(cam.tPhi -cam.phi )*Math.min(1,dt*10);
  cam.zoom +=(cam.tZoom-cam.zoom)*Math.min(1,dt*7);

  stepMeteors(dt);
  render();
  requestAnimationFrame(frame);
}

/* =========================== interaction =========================== */
canvas.addEventListener('pointerdown',e=>{
  canvas.setPointerCapture(e.pointerId);
  pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});
  if(pointers.size===1){ dragging=true; cam.vPhi=0; cam.vTilt=0; dragAnchor(e); }
  else if(pointers.size===2){
    dragging=false;
    const[a,b]=[...pointers.values()];
    pinchD0=Math.hypot(a.x-b.x,a.y-b.y); pinchZ0=cam.tZoom;
  }
  mouse.x=e.clientX; mouse.y=e.clientY; mouse.has=true; lastInteract=wallT;
});
function dragAnchor(e){ dragAnchor.lx=e.clientX; dragAnchor.ly=e.clientY; }
canvas.addEventListener('pointermove',e=>{
  mouse.x=e.clientX; mouse.y=e.clientY; mouse.has=true;
  if(pointers.has(e.pointerId)) pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});
  if(pointers.size===2){
    const[a,b]=[...pointers.values()];
    const d=Math.hypot(a.x-b.x,a.y-b.y);
    if(pinchD0>0) cam.tZoom=clamp(pinchZ0*d/pinchD0,0.5,2.4);
    lastInteract=wallT; return;
  }
  if(dragging){
    const dx=e.clientX-dragAnchor.lx, dy=e.clientY-dragAnchor.ly;
    dragAnchor.lx=e.clientX; dragAnchor.ly=e.clientY;
    cam.tPhi  += dx*0.005;
    cam.tTilt += -dy*0.0045;
    cam.vPhi  = dx*0.0018;
    cam.vTilt = -dy*0.0016;
    lastInteract=wallT;
  }
});
['pointerup','pointercancel'].forEach(ev=>canvas.addEventListener(ev,e=>{
  pointers.delete(e.pointerId);
  if(pointers.size<2) pinchD0=0;
  if(pointers.size===0) dragging=false;
  else if(pointers.size===1){ const[p]=[...pointers.values()]; dragging=true; dragAnchor(p); }
}));
canvas.addEventListener('pointerleave',()=>{ if(pointers.size===0) mouse.has=false; });
canvas.addEventListener('wheel',e=>{
  e.preventDefault();
  cam.tZoom=clamp(cam.tZoom*Math.exp(-e.deltaY*0.0011),0.5,2.4);
  lastInteract=wallT;
},{passive:false});
window.addEventListener('keydown',e=>{
  if(e.code==='Space'){ if(e.repeat)return; e.preventDefault();
    paused=!paused; document.body.classList.toggle('paused',paused); }
  else if(e.key==='+'||e.key==='=') simSpeed=clamp(simSpeed*1.3,0.25,6);
  else if(e.key==='-'||e.key==='_') simSpeed=clamp(simSpeed/1.3,0.25,6);
  else if(e.key==='r'||e.key==='R'){
    cam.tTilt=DEF_TILT; cam.tPhi=DEF_PHI; cam.tZoom=1; cam.vPhi=0; cam.vTilt=0; lastInteract=wallT;
  }
});

/* =============================== boot =============================== */
function resize(){
  DPR=Math.min(2,window.devicePixelRatio||1);
  W=innerWidth; H=innerHeight;
  canvas.width=W*DPR; canvas.height=H*DPR;
  canvas.style.width=W+'px'; canvas.style.height=H+'px';
  CX=W/2; CY=H/2;
  U=Math.min(W,H)/760;
  buildBackground();
}
window.addEventListener('resize',resize);
resize();
requestAnimationFrame(frame);
</script>
